-- AL-QUR'AN HADIS MI/MTs/MA/MAK | MI Fase C [3 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MI', 'madrasah', NULL, 'AL-QUR''AN HADIS MI/MTs/MA/MAK', 'C', 'IV-VI', NULL, '[{"nama_elemen":"Fase C (Kelas","capaian_pembelajaran":"5 dan 6 MI) Pada akhir fase C, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"1","capaian_pembelajaran":"Pemahaman Konsep Tajwid Menerapkan hukum bacaan mim sukun, waqaf wasal, dan hukum ra'' tafkhim dan tarqiq, jawazul wajhain dalam praktik membaca Al-Qur''an dengan baik dan benar. Al-Qur''an Menghafal dan menulis ayat/surah dalam Al-Qur''an tentang ciri-ciri orang munafik, menyayangi anak yatim, keutamaan memberi, amal saleh; menjelaskan arti dan isi kandungannya agar dapat menerapkan dalam kehidupan sehari-hari. Hadis Menghafal dan menulis hadis tentang ciri-ciri orang munafik, menyayangi anak yatim, keutamaan memberi, dan amal saleh; menjelaskan arti dan isi kandungannya agar dapat menerapkan dalam kehidupan sehari-hari."},{"nama_elemen":"2","capaian_pembelajaran":"Keterampilan Proses Mengamati Murid mengamati fenomena, fakta dan peristiwa secara sederhana yang relevan dengan Al-Qur''an dan Hadis; mengidentifikasi dan mengklasifikasikan, kemudian mencatat hasil pengamatan dan mencari sisi persamaan atau perbedaan. Mempertanyakan dan memprediksi Dengan bantuan guru, murid membuat pertanyaan ilmiah yang mengarah pada konten yang disajikan serta memprediksi jawaban. - 14 - Merencanakan dan melakukan penyelidikan Dengan bantuan guru, murid melakukan langkah-langkah kongkrit dalam menemukan jawaban yang diajukan melalui observasi dan penyelidikan. Memproses serta menganalisis data dan informasi Dengan bantuan guru, murid mengolah data dan informasi yang diperoleh dalam bentuk gambar atau diagram, kemudian membandingkan antara hasil dan prediksi dengan penjelasan yang memadai. Mengevaluasi dan merefleksi Murid melakukan evaluasi terhadap proses-proses yang telah dilalui maupun hasil yang didapatkan. Mengomunikasikan hasil Murid menyajikan hasil baik secara lisan maupun tulisan melalui berbagai media."}]', NULL, 15, false, NOW(), NOW())
