INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MTs', 'madrasah', NULL, 'AL-QUR''AN HADIS MI/MTs/MA/MAK', 'D', 'VII-IX', NULL, '[{"nama_elemen":"Fase D (Kelas","capaian_pembelajaran":"7, 8, dan 9 MTs) Pada akhir fase D, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"1","capaian_pembelajaran":"Pemahaman Konsep Tajwid Menerapkan hukum bacaan mad tabi''i, mad far''i, dan bacaan garib agar dapat membaca Al-Qur''an secara baik dan benar. Al-Qur''an Merefleksi isi kandungan ayat-ayat Al-Qur''an secara tekstual dan kontekstual tentang kekuasaan dan rahmat Allah Swt., sifat pemurah, optimis dan sabar, infak di jalan Allah Swt., kehidupan dunia yang sementara dan akhirat yang kekal, sikap peduli terhadap masyarakat dan lingkungannya, bersikap jujur dalam bemuamalah, semangat menuntut ilmu. Hadis Merefleksi isi kandungan hadis secara tekstual dan kontekstual tentang kekuasaan dan rahmat Allah Swt., sifat pemurah, optimis dan sabar, infak di jalan Allah Swt., kehidupan dunia yang sementara dan akhirat yang kekal, sikap peduli terhadap masyarakat dan lingkungannya, bersikap jujur dalam bemuamalah, semangat menuntut ilmu. - 15 -"},{"nama_elemen":"2","capaian_pembelajaran":"Keterampilan Proses Mengamati Melakukan pengamatan terhadap perilaku masyarakat tentang tema-tema terkait dan mencatat hasil pengamatan. Merencanakan dan melakukan penyelidikan Merencanakan dan membuat tahapan, langkah-langkah operasional untuk menjawab pertanyaan. Memproses, menganalisis data dan informasi Mengolah data dalam bentuk tabel atau diagram serta menjelaskan hasil pengamatan; menganalisis permasalahan dan informasi. Mengevaluasi dan refleksi Mengidentifikasi kemungkinan penjelasan alternatif dalam rangka memberi ide atau solusi dari permasalahan; mengevaluasi kesimpulan, serta menjelaskan cara spesifik untuk meningkatkan kualitas data. Mengomunikasikan hasil Mengomunikasikan hasil analisis secara sistematis dan utuh yang ditunjang dengan argumen dan bahasa yang sesuai."}]', NULL, 15, false, NOW(), NOW())
