-- AL-QUR'AN HADIS MAPK | MA Fase F [9 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MA', 'madrasah', NULL, 'AL-QUR''AN HADIS MAPK', 'F', 'XII', NULL, '[{"nama_elemen":"Fase F (Kelas","capaian_pembelajaran":"XI dan XII Madrasah Aliyah Program Keagamaan) Pada akhir fase F, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"1","capaian_pembelajaran":"Pemahaman Konsep Menganalisis teks berbahasa Arab, tafsir ayat Al-Qur''an tentang mensyukuri nikmat Allah Swt., sabar dalam menghadapi ujian dan cobaan, tanggung jawab terhadap diri sendiri, keluarga, dan masyarakat, makanan minuman yang halal dan baik, makanan minuman yang haram, toleransi dan etika pergaulan, kesantunan, mencintai kedamaian, sikap peduli dan gemar berbagi, hidup gotong royong, amar ma''ruf nahi munkar, kewajiban berdakwah, sikap peduli terhadap pelestarian lingkungan hidup musyawarah, amanah dalam menjalankan kepemimpinan, dan sikap berlaku adil serta jujur."},{"nama_elemen":"2","capaian_pembelajaran":"Keterampilan Proses Mengamati Mengamati berbagai fenomena dan peristiwa dan menghubungkannya dengan ayat yang relevan. Mempertanyakan dan memprediksi Mengidentifikasi berbagai pertanyaan dan memperkirakan jawabannya sementara atas hasil pengamatan yang telah dilakukan. Merencanakan dan melakukan penelitian Berdasarkan identifikasi pertanyaan yang telah dilakukan, murid berusaha mencari jawaban dengan menelusuri berbagai sumber, baik tekstual maupun kontekstual. Memproses, menganalisis data dan informasi Menganalisis berbagai data yang masuk dari hasil hasil penelusuran berbagai sumber dan data. Mengevaluasi dan Refleksi Mengevaluasi dan menyimpulkan hasil analisis terhadap data yang terkumpul dan melalukan refleksi dari hasil penerapan. Mengomunikasikan hasil Menyampaikan hasil keseluruhan proses yang telah dilalui melalui berbagai media yang mudah dipahami. - 24 -"},{"nama_elemen":"CAPAIAN PEMBELAJARAN AL-QUR''AN HADIS (HADIS)","capaian_pembelajaran":"A. Rasional Pelajaran Hadis sangat penting dalam Pendidikan Agama Islam karena hadis merupakan sumber ajaran Islam kedua setelah Al-Qur''an, yang menjelaskan, merinci, dan memberikan contoh praktis dari ajaran Al-Qur''an dalam berbagai aspek kehidupan. Mempelajari hadis membantu umat Islam untuk memahami, menghayati, dan mengamalkan ajaran Islam secara lebih mendalam dan kontekstual. Adapun landasan mata pelajaran Hadis menjadi penting. Pertama, hadis merupakan sumber hukum Islam yang kedua setelah Al-Qur''an. Mempelajari hadis memungkinkan umat Islam untuk memahami hukum-hukum Islam secara lebih komprehensif dan detail. Kedua, hadis berfungsi menjelaskan dan merinci isi kandungan Al-Qur''an. Dengan mempelajari hadis, umat Islam dapat memahami maksud dan tujuan dari ayat-ayat Al-Qur''an dengan lebih jelas karena berisi contoh praktis dari Nabi Muhammad saw. Ketiga, mempelajari hadis merupakan salah satu sarana membentuk karakter mulia dari murid. Melalui pelajaran hadis, murid dapat belajar tentang akhlak mulia dan karakter terpuji yang dicontohkan oleh Nabi Muhammad saw. Hal ini membantu dalam pembentukan karakter siswa yang Islami dan berakhlak mulia. Mata pelajaran ini membahas hadis secara tematik. Terdapat banyak pertimbangan dalam penentuan tema kajian yang dipilih. Salah satu aspek yang dipertimbangkan dalam penentuan tema adalah tumbuhnya kecintaan murid kepada Allah dan Rasul-Nya, cinta ilmu, cinta diri dan sesama, cinta lingkungan, dan cinta tanah air. Panca Cinta tersebut menjadi dasar sekaligus tujuan dalam mempelajari tema-tema hadis yang ditentukan. B. Tujuan"},{"nama_elemen":"Meningkatkan kesadaran,","capaian_pembelajaran":"ketaatan, dan kecintaan murid kepada Allah dan Rasul-Nya, melalui penghayatan terhadap hadis-hadis yang relevan."},{"nama_elemen":"Meningkatkan kecintaan","capaian_pembelajaran":"dan semangat murid dalam menuntut ilmu."},{"nama_elemen":"Membekali murid","capaian_pembelajaran":"untuk siap hidup bersama dengan orang lain (hablun minannas) atas dasar cinta kepada sesama sebagaimana - 25 - cinta kepada diri sendiri berdasarkan hadis-hadis yang relevan dan kontekstual."},{"nama_elemen":"Meningkatkan pemahaman","capaian_pembelajaran":"dan penghayatan murid terhadap hadis-hadis yang memperkuat kecintaan pada lingkungan hidup."},{"nama_elemen":"Meningkatkan kecintaan","capaian_pembelajaran":"terhadap tanah air melalui pemahaman dan penghayatan terhadap hadis-hadis yang berkaitan dengan kehidupan berbangsa, kesiapan menjadi pemimpin yang amanah, jujur, dan adil. C. Karakteristik Tujuan akhir dari mata pelajaran hadis adalah mengamalkan hadis secara kontekstual dalam kehidupan sehari-hari. Oleh karena itu, ada dua aspek yang perlu mendapatkan penekanan, yakni pemahaman konsep dari makna hadis yang dipelajari dan keterampilan proses dalam penerapan hadis dimaksud. Pada aspek pemahaman konsep, murid mempelajari penjelasan (syarah) ulama dari teks berbahasa Arab tentang hadis tertentu untuk kemudian direfleksikan dalam proses penerapan. Selain mengamalkan isi kandungan hadis yang dipelajari, juga mengajarkan dan mengomunikasikan hasil pemahaman kepada orang lain. Oleh karena itu, pada aspek keterampilan proses selain terdapat aspek pemahaman, penerapan dan refleksi terhadap hasil penerapan, pada saat yang sama murid mampu memahami, menganalisis dan mengomunikasikan hasil pemahaman kepada orang lain. Keseluruhan tahapan, mulai dari pemahaman, penerapan, hingga refleksi diharapkan mampu menumbuhkan dan meningkatkan lima aspek cinta dalam diri murid, yakni cinta Allah dan Rasul-Nya, cinta ilmu, cinta diri dan sesama, cinta lingkungan, dan cinta tanah air. Elemen dan deskripsi mata pelajaran hadis adalah sebagai berikut. Elemen Deskripsi Pemahaman Ketentuan dan petunjuk hadis tentang: Konsep Cinta Allah dan Rasul-Nya Meliputi hadis-hadis tentang kebesaran dan kekuasaan Allah Swt., menaati Allah Swt. dan Rasulullah saw., sikap ikhlas beribadah, mensyukuri nikmat Allah Swt., sabar dalam menjalankan ketaatan, menghindari maksiat dan menghadapi ujian. Keterampilan Proses - 26 - Cinta ilmu Meliputi hadis-hadis tematik tentang semangat menuntut ilmu dan mengembangkan ilmu pengetahuan, menghormati dan menghargai guru. Cinta diri dan sesama manusia Meliputi pemahaman hadis tentang menghindari pergaulan bebas, etos kerja, tanggung jawab terhadap diri, keluarga dan masyarakat, berkompetisi dalam kebaikan, makanan dan minuman halal dan baik, serta menghindari makanan dan minuman haram yang membahayakan jasmani dan rohani, berbuat baik kepada kedua orang tua, toleransi dan etika pergaulan, kesantunan, mencintai kedamaian, sikap peduli dan gemar berbagi, hidup gotong royong, amar ma''ruf nahi munkar, dan kewajiban berdakwah. Cinta lingkungan Meliputi hadis tentang sikap peduli terhadap pelestarian lingkungan hidup sebagai dasar pemahaman konsep ekoteologi. Cinta tanah air Meliputi hadis-hadis tematik tentang sikap amanah dalam kepemimpinan, musyawarah, dan berlaku adil dan jujur dalam kepemimpinan. Keterampilan ilmiah yang digunakan dalam proses belajar, agar murid mampu menemukan dan mengembangkan pengetahuan, keterampilan, nilai, dan sikap serta menerapkannya dalam kehidupan. Keterampilan proses ini meliputi: mengamati; mempertanyakan dan memprediksi; merencanakan dan melakukan penyelidikan; memproses serta menganalisis data dan informasi; mengevaluasi d"}]', NULL, 46, false, NOW(), NOW())
ON CONFLICT (sumber_regulasi, jalur, jenjang, tipe_pendidikan, mapel_kode, fase)
DO UPDATE SET elemen = EXCLUDED.elemen, mapel_nama = EXCLUDED.mapel_nama, updated_at = NOW();
-- AKIDAH AKHLAK MI/MTs/MA/MAK | MI Fase C [3 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MI', 'madrasah', NULL, 'AKIDAH AKHLAK MI/MTs/MA/MAK', 'C', 'IV-VI', NULL, '[{"nama_elemen":"Fase C (Kelas","capaian_pembelajaran":"V dan VI Madrasah Ibtidaiyah) Pada akhir fase C, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"1","capaian_pembelajaran":"Pemahaman Konsep Akidah Menerapkan perilaku yang mencerminkan sifat asmaulhusna (al-Qawiyy, al-Khabir, al-Muhyi, al-Wahid, alAhad, as-Samad, al-Ghaffar, dan al-Waasi''); menjelaskan hari akhir (kiamat), qada dan qadar. Akhlak Menjelaskan dan menerapkan kalimah thayyibah (istigfar, hauqalah, tarji'', dan tahlil); menerapkan dan merefleksikan akhlak terpuji (sabar, disiplin, mandiri, pemaaf, tanggung jawab, adil, dan bijaksana), serta cara menghindari akhlak tercela (pemarah, fasik, pilih kasih, iri hati, dan egois). Adab Mengidentifikasi dan menerapkan adab bertamu, adab kepada tetangga, dan lingkungan. Kisah Keteladanan Menceritakan dan menerapkan sikap keberanian dan teguh pendirian melalui kisah Nabi Musa a.s. dan sikap sabar melalui kisah Nabi Isa a.s."},{"nama_elemen":"2","capaian_pembelajaran":"Keterampilan Proses Keterampilan proses pada mata pelajaran Akidah Akhlak meliputi kegiatan sebagai berikut. Mengamati Murid mengamati fenomena kehidupan atau kejadian nyata di lingkungan sekitar yang terkait dengan materi berupa gambar, video, atau bentuk lainnya untuk memahami nilainilai yang dipelajari. Menanya dan mengumpulkan informasi Murid diajak bertanya untuk membangkitkan rasa ingin tahu. Kemudian, murid mengumpulkan informasi dari berbagai sumber yang relevan. Menganalisis dan menyimpulkan Melalui bimbingan guru, murid berdiskusi kelompok untuk menganalisis informasi yang telah dikumpulkan. Kemudian - 46 - bersama-sama menyimpulkan nilai-nilai penting dari materi yang telah dipelajari. Mengomunikasikan Murid menyampaikan pemahaman mereka dengan cara yang menyenangkan dan kreatif agar dapat saling belajar dan memberi masukan. Menerapkan Murid menerapkan nilai-nilai yang telah dipelajari dalam kehidupan sehari-hari. Merefleksikan dan rencana tindak lanjut Murid merefleksikan perilaku mereka yang telah menerapkan akhlak terpuji dan menghindari akhlak tercela. Mereka mengevaluasi pengalaman harian dan menuliskan satu hal baik yang akan dilakukan."}]', NULL, 125, false, NOW(), NOW())
ON CONFLICT (sumber_regulasi, jalur, jenjang, tipe_pendidikan, mapel_kode, fase)
