-- AKIDAH AKHLAK MI/MTs/MA/MAK | MTs Fase D [3 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MTs', 'madrasah', NULL, 'AKIDAH AKHLAK MI/MTs/MA/MAK', 'D', 'VII-IX', NULL, '[{"nama_elemen":"Fase D (Kelas","capaian_pembelajaran":"VII, VIII, dan IX Madrasah Tsanawiyah) Pada akhir fase D, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"1","capaian_pembelajaran":"Pemahaman Konsep Akidah Menganalisis akidah Islam (iman, Islam, ihsan); menerapkan perilaku yang mencerminkan asmaulhusna (al-Bashith, alGani, ar-Ra''uf, al-Barr, al-Fattah, al-''Adl, al-Wakiil, atThawwab, al-Lathif, al-Qohhar); menganalisis enam rukun iman (Iman kepada Allah, malaikat, kitab, rasul, hari kiamat, qada dan qadar). Akhlak Menerapkan dan merefleksikan akhlak terpuji (tobat, taat, istikamah, ikhlas, ikhtiar, tawakal, kanaah, sabar, syukur, husnuzan, tawaduk, tasamuh, ta''awun, berilmu, kreatif, produktif, dan inovatif) dan cara menghindari akhlak tercela (riya, nifak, putus asa, ananiyah, dendam, ghadhab, khalwat (pacaran) dan ikhtilat). Adab Menerapkan adab salat dan zikir, membaca Al-Qur''an dan berdoa; menerapkan dan merefleksikan adab kepada orang tua, guru, saudara, tetangga, dan teman, adab berjalan dan berpakaian, serta menyusun dan menerapkan strategi bijak adab bermedia sosial. - 47 - Kisah Keteladanan Menganalisis dan menerapkan keteladanan dari kisah-kisah Nabi (Nabi Yunus a.s., Nabi Ayub a.s., Nabi Daud a.s., dan Nabi Sulaiman a.s.) dan keteladanan dari kisah Khulafaurasyidin (Abu Bakar, Umar bin Khattab, Usman bin Affan, dan Ali bin Abi Thalib)."},{"nama_elemen":"2","capaian_pembelajaran":"Keterampilan Proses Keterampilan proses pada mata pelajaran Akidah Akhlak meliputi kegiatan sebagai berikut. Mengamati, mengidentifikasi, dan menanya Murid dilatih untuk mengamati fenomena kehidupan sehari-hari dan mengidentifikasi permasalahan yang terjadi. Melalui bimbingan guru, murid diajak untuk mengajukan pertanyaan guna menggali serta mengklarifikasi informasi. Mengumpulkan informasi, menganalisis, dan memecahkan masalah. Berdasarkan hasil pengamatan, murid secara kolaboratif mengumpulkan, mengolah, dan mendokumentasikan informasi. Kemudian, menganalisis konsep-konsep inti dalam Islam dan menilai relevansinya sebagai solusi terhadap permasalahan yang dihadapi. Proses ini mendorong murid menemukan pemecahan masalah yang konkret dan aplikatif. Menyimpulkan Setelah menganalisis dan menemukan solusi, murid secara kolaboratif merumuskan kesimpulan yang relevan. Kesimpulan ini tidak hanya berisi jawaban atas pertanyaan awal, tetapi juga mencakup pemahaman mendalam tentang bagaimana prinsip-prinsip Islam dapat diterapkan untuk menyelesaikan masalah yang diamati. Mengomunikasikan hasil Murid menyajikan hasil temuan mereka secara kolaboratif. Tahap ini melatih mereka menjadi komunikator yang mampu menyajikan solusi secara efektif dan logis. - 48 - Komunikasi dapat dilakukan dalam berbagai bentuk, seperti presentasi, laporan tertulis, poster, flyer, infografik, video edukasi atau media kreatif lainnya, sehingga kesimpulan yang diperoleh dapat dibagikan, diberikan umpan balik, dan diterapkan. Menerapkan Setelah menemukan solusi, murid mampu menerapkan perilaku yang mencerminkan akidah Islam, beriman pada rukun iman, serta mengamalkan asmaul husna. Murid juga membiasakan akhlak terpuji, menghindari akhlak tercela, dan mengaplikasikan adab dalam berbagai konteks, baik dalam ibadah maupun dalam interaksi sosial, termasuk dalam penggunaan media sosial. Murid menyusun dan melaksanakan strategi bijak dalam bermedia sosial, menghadapi konten negatif dengan tanggung jawab, serta mampu mengambil hikmah dari kisah-kisah teladan untuk dijadikan panduan dalam menghadapi tantangan kehidupan sehari-hari. Merefleksikan dan rencana tindak lanjut Murid mampu merefleksikan perilaku mereka sendiri dan mengevaluasi sejauh mana mereka telah mengamalkan akhlak terpuji, menghindari akhlak tercela, menghubungkan konsep-konsep akidah, ibadah, dan akhlak dengan pengalaman hidup mereka, sehingga ajaran Islam menjadi lebih bermakna."}]', NULL, 125, false, NOW(), NOW())
ON CONFLICT (sumber_regulasi, jalur, jenjang, tipe_pendidikan, mapel_kode, fase)
DO UPDATE SET elemen = EXCLUDED.elemen, mapel_nama = EXCLUDED.mapel_nama, updated_at = NOW();
-- AKIDAH AKHLAK MI/MTs/MA/MAK | MA Fase E [3 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MA', 'madrasah', NULL, 'AKIDAH AKHLAK MI/MTs/MA/MAK', 'E', 'X-XI', NULL, '[{"nama_elemen":"Fase E (Kelas","capaian_pembelajaran":"X Madrasah Aliyah/Madrasah Aliyah Kejuruan Pada akhir Fase E, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"1","capaian_pembelajaran":"Pemahaman Konsep Akidah Menganalisis sifat wajib Allah Swt. (nafsiyah, salbiyah, ma''ani, dan ma''nawiyah), mustahil, dan jaiz; menganalisis dan menerapkan perilaku yang mencerminkan asmaulhusna (al-Karim, al-Hakam, al-Haq, al-Hafiz, alWahhab, ar-Rakib, al-Mubdi'', dan al-Qoyyum). - 49 - Akhlak Menganalisis dan menerapkan akhlak terpuji (hikmah, iffah, syaja''ah, dan ''adalah) dan cara menghindari akhlak tercela (hubbud-dunya, hasad, ujub, sombong, syahwat, licik, tamak, zalim, dan diskriminatif). Adab Menganalisis dalil berbakti kepada orang tua dan guru dan merefleksikan hikmah berbakti kepada orang tua dan guru. Kisah Keteladanan Menganalisis dan menerapkan keteladanan kisah Nabi Luth a.s. dan Ashabulkahfi dalam kesabaran, ketangguhan, dan keberanian dalam menegakkan amar ma''ruf dan nahi munkar."},{"nama_elemen":"2","capaian_pembelajaran":"Keterampilan Proses Keterampilan proses pada mata pelajaran Akidah Akhlak meliputi kegiatan sebagai berikut. Mengamati, mengidentifikasi, dan menanya Murid dilatih untuk mengamati fenomena kehidupan seharihari dan mengidentifikasi permasalahan yang terjadi. Melalui bimbingan guru, murid diajak untuk mengajukan pertanyaan guna menggali serta mengklarifikasi informasi. Mengumpulkan informasi, menganalisis, dan memecahkan masalah Berdasarkan hasil pengamatan, murid secara kolaboratif mengumpulkan, mengolah, dan mendokumentasikan informasi. Kemudian, menganalisis konsep-konsep tentang sifat Allah Swt., akhlak terpuji dan tercela, adab, serta kisahkisah teladan, dan menilai relevansinya sebagai solusi. Proses ini mendorong murid menemukan pemecahan masalah yang konkret. Menyimpulkan Setelah menganalisis dan menemukan solusi, murid secara kolaboratif merumuskan kesimpulan yang relevan. Kesimpulan ini tidak hanya berisi jawaban atas pertanyaan awal, tetapi juga mencakup pemahaman mendalam tentang bagaimana prinsip-prinsip Islam dapat diterapkan untuk menyelesaikan masalah yang diamati. - 50 - Mengomunikasikan hasil Murid menyajikan hasil temuan mereka secara kolaboratif. Tahap ini melatih mereka menjadi komunikator yang mampu menyajikan solusi secara efektif dan logis. Komunikasi dapat dilakukan melalui berbagai media, seperti laporan tertulis, presentasi lisan, poster, flyer, infografik, video edukasi, atau media kreatif lainnya, sehingga kesimpulan yang diperoleh dapat dibagikan, diberikan umpan balik dan diterapkan. Menerapkan Setelah menemukan solusi, murid mampu menerapkan perilaku yang mencerminkan sifat wajib, mustahil, dan jaiz Allah Swt., dan mengamalkan asmaul husna. Murid juga membiasakan akhlak terpuji, menghindari akhlak tercela, dan mengaplikasikan adab dalam interaksi sosial, serta mampu mengambil hikmah dari kisah-kisah teladan untuk dijadikan panduan dalam menghadapi tantangan kehidupan seharihari. Merefleksikan dan rencana tindak lanjut Murid mampu merefleksikan perilaku mereka sendiri dan mengevaluasi sejauh mana mereka telah mengamalkan akhlak terpuji, menghindari akhlak tercela, menghubungkan konsep-konsep akidah, ibadah, dan akhlak dengan pengalaman hidup mereka, sehingga ajaran Islam menjadi lebih bermakna."}]', NULL, 125, false, NOW(), NOW())
