INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MI', 'madrasah', NULL, 'FIKIH MI/MTs/MA/MAK', 'C', 'IV-VI', NULL, '[{"nama_elemen":"Fase C (Umumnya","capaian_pembelajaran":"untuk Kelas V dan VI MI) Pada akhir fase C, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Pemahaman Konsep Ibadah Membedakan zakat","capaian_pembelajaran":"fitrah, infak dan sedekah; mengklasifikasikan jenis-jenis hewan kurban; menyebutkan hikmah dari pelaksanaan kurban; mengurutkan pelaksanaan tata cara haji dan umrah; menjelaskan ketentuan halal dan haram. Muamalah Menceritakan pengalaman praktik jual beli; mengilustrasikan ketentuan pinjam meminjam; menjelaskan pentingnya menghindari perbuatan gasab, ketentuan barang temuan/ luqathah."},{"nama_elemen":"Keterampilan Proses Keterampilan proses","capaian_pembelajaran":"pada fase ini meliputi kegiatan. Mengamati Melakukan pengamatan ibadah sebagai pengamalan rukun Islam dan kegiatan muamalah yang terjadi di masyarakat serta mencatat hasil pengamatan. Menanya Mengidentifikasi dan menyusun daftar pertanyaan yang akan digunakan untuk menggali data terhadap permasalahan fikih ibadah dan muamalah yang diangkat sebagai masalah penelitian. Mengumpulkan data Mencari informasi dari beberapa sumber primer maupun sekunder melalui wawancara, observasi dan lain sebagainya untuk menjawab pertanyaan yang disajikan. Menganalisis data Menganalisis data dengan melakukan komparasi antara ketentuan ibadah dan muamalah yang sesuai syariat dengan realitas yang dilakukan seseorang. Menyimpulkan dan merefleksikan Menarasikan temuan hasil investigasi berupa kritik sosial berupa kritik sosial dari sebuah fenomena sosial keagamaan yang terjadi di masyarakat, kemudian - 71 - merefleksikan hasil temuannya kepada diri mereka sendiri agar menjadi muslim yang semakin baik. Mengomunikasikan hasil Menyajikan informasi secara lisan, tulisan, dan/atau media lain dalam bentuk digital maupun nondigital."}]', NULL, 169, false, NOW(), NOW())
