INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MTs', 'madrasah', NULL, 'FIKIH MI/MTs/MA/MAK', 'D', 'VII-IX', NULL, '[{"nama_elemen":"Fase D (Umumnya","capaian_pembelajaran":"untuk Kelas VII, VIII, dan XI MTs) Pada akhir fase D, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Pemahaman Konsep Ibadah","capaian_pembelajaran":"Menerapkan dan menganalisis ketentuan taharah dari hadas dan najis, macam-macam salat dan rukhsahnya; menerjemahkan bacaan salat; membedakan dan menganalisis macam-macam sujud; menerapkan dan menganalisis ketentuan puasa Ramadan dan rangkaian ibadah sunah yang menyertainya; menerapkan dan menganalisis ketentuan puasa sunah, jenis-jenis infak dan zakat; membedakan dan menganalisis ketentuan kurban dan akikah; pelaksanaan haji dan umrah beserta macam- macamnya; mengklasifikasi dan menganalisis makanan, minuman, dan hewan yang halal dan haram; menjelaskan dan menerapkan ketentuan pemulasaraan jenazah. Muamalah Menganalisis ketentuan jual beli, khiyar, qiradl, larangan riba, `ariyah, wadi''ah, hutang-piutang, gadai, hiwalah, ijarah; dan menjelaskan ketentuan warisan."},{"nama_elemen":"Keterampilan Proses Keterampilan proses","capaian_pembelajaran":"pada fase ini meliputi kegiatan. Mengamati Melakukan pengamatan ibadah sebagai pengamalan rukun Islam dan kegiatan muamalah yang terjadi di masyarakat serta mencatat hasil pengamatan. Menanya Mengidentifikasi dan menyusun daftar pertanyaan yang akan digunakan untuk menggali data terhadap permasalahan fikih ibadah dan muamalah yang diangkat sebagai masalah penelitian. - 72 - Mengumpulkan data Mencari informasi dari beberapa sumber primer maupun sekunder melalui wawancara, observasi dan lain sebagainya untuk menjawab pertanyaan yang disajikan. Menganalisis data Menganalisis data dengan melakukan komparasi antara ketentuan ibadah dan muamalah yang sesuai syariat dengan realitas yang dilakukan seseorang. Menyimpulkan dan merefleksikan Menarasikan temuan hasil investigasi berupa kritik sosial berupa kritik sosial dari sebuah fenomena sosial keagamaan yang terjadi di masyarakat, kemudian merefleksikan hasil temuannya kepada diri mereka sendiri agar menjadi muslim yang semakin baik. Mengomunikasikan hasil Menyajikan informasi secara lisan, tulisan, dan/atau media lain dalam bentuk digital maupun nondigital."}]', NULL, 169, false, NOW(), NOW())
ON CONFLICT (sumber_regulasi, jalur, jenjang, tipe_pendidikan, mapel_kode, fase)
