INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MA', 'madrasah', NULL, 'FIKIH MI/MTs/MA/MAK', 'E', 'X-XI', NULL, '[{"nama_elemen":"Fase E (Umumnya","capaian_pembelajaran":"untuk Kelas X MA/MAK) Pada akhir fase E, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Pemahaman Konsep Ibadah Memecahkan masalah","capaian_pembelajaran":"dalam praktik taharah, salat dalam berbagai situasi seperti jamak, qasar, salat dalam kondisi sakit, salat dalam kendaraan dan keadaan darurat; merefleksikan pelaksanaan zakat profesi dan wakaf; menganalisis persoalan haji dan umrah; menerapkan dan merefleksi pelaksanaan pemulasaraan jenazah; menganalisis pelaksanaan sertifikasi halal dan tata cara penyembelihan hewan. Muamalah Menganalisis konsep kepemilikan dan perpindahannya meliputi sebab - sebab kepemilikan, akad, ihyaul mawat, jual beli, transaksi mengandung riba, khiyar, salam, al-hajru; menganalisis kerja sama permodalan dalam muamalah Islam seperti mudharabah, murabahah, syirkah, syuf''ah, wakalah, shulhu, dlaman, kafalah, wadiah, dan rahn; merefleksikan - 73 - praktik transaksi online dalam perspektif Islam meliputi jual beli, pembayaran, pinjaman, dan judi online serta dampak yang menyertainya."},{"nama_elemen":"Keterampilan Proses Keterampilan proses","capaian_pembelajaran":"pada fase ini meliputi kegiatan. Mengamati Melakukan pengamatan ibadah sebagai pengamalan rukun Islam dan kegiatan muamalah yang terjadi di masyarakat serta mencatat hasil pengamatan. Menanya Mengidentifikasi dan menyusun daftar pertanyaan yang akan digunakan untuk menggali data terhadap permasalahan fikih ibadah dan muamalah yang diangkat sebagai masalah penelitian. Mengumpulkan data Mencari informasi dari beberapa sumber primer maupun sekunder melalui wawancara, observasi dan lain sebagainya untuk menjawab pertanyaan yang disajikan. Menganalisis data Menganalisis data dengan melakukan komparasi antara ketentuan ibadah dan muamalah yang sesuai syariat dengan realitas yang dilakukan seseorang. Menyimpulkan dan merefleksikan Menarasikan temuan hasil investigasi berupa kritik sosial berupa kritik sosial dari sebuah fenomena sosial keagamaan yang terjadi di masyarakat, kemudian merefleksikan hasil temuannya kepada diri mereka sendiri agar menjadi muslim yang semakin baik. Mengomunikasikan hasil Menyajikan informasi secara lisan, tulisan, dan/atau media lain dalam bentuk digital maupun nondigital."}]', NULL, 169, false, NOW(), NOW())
