-- FIKIH MAPk | MA Fase F [10 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MA', 'madrasah', NULL, 'FIKIH MAPk', 'F', 'XII', NULL, '[{"nama_elemen":"Fase F (Kelas","capaian_pembelajaran":"XI dan XII Madrasah Aliyah Program Keagamaan) Pada akhir fase F, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Pemahaman Konsep","capaian_pembelajaran":"Menganalisis dalil dan istidlal fuqaha tentang macam-macam kepemilikan dan perpindahannya serta hal-hal yang dilarang, macam-macam kerjasama dan permodalan, perbankan syari''ah, dan transaksi online; menganalisis ketentuan jinayah, hudud, bughat, riddah dan ketentuan peradilan dalam Islam serta implementasinya dalam konteks - 79 - masyarakat yang majemuk dalam bingkai Islam yang rahmatan lil ''alamin; menganalisis konsep Islam tentang perkawinan, talak, rujuk, nusyuz, wasiat, Ilmu Waris dan implementasinya dalam konteks keindonesiaan."},{"nama_elemen":"Keterampilan Proses Keterampilan ilmiah","capaian_pembelajaran":"yang digunakan dalam pembelajaran elemen pemahaman fikih. Mengamati Melakukan pengamatan terhadap fenomena sosial dan keagamaan di masyarakat yang berkaitan dengan Fikih Muamalah. Menanya Mengidentifikasi pertanyaan yang dapat diteliti secara fikih yang setidaknya mendiskripsikan perilaku masyarakat muslim dalam bermuamalah. Mengumpulkan data Murid mencari informasi berdasarkan pertanyaan yang telah diidentifikasi dari sumber primer atau sekunder melalui wawancara, observasi dan lain sebagainya. Menganalisis data Dengan bimbingan guru, murid menganalisis data dengan melakukan komparasi antara ketentuan hukum syar''i yang seharusnya dengan realitas yang terjadi di masyarakat. Menyimpulkan Murid menarasikan temuan hasil investigasi berupa kritik sosial dari sebuah fenomena sosial keagamaan yang terjadi di masyarakat. Mengomunikasikan Murid menyajikan informasi secara lisan, tulisan atau media lain dalam bentuk digital maupun nondigital."},{"nama_elemen":"CAPAIAN PEMBELAJARAN MATA PELAJARAN USHUL FIKIH A. Rasional","capaian_pembelajaran":"Dinamika masyarakat muslim yang mengalami perkembangan pesat seiring kemajuan ilmu pengetahuan dan teknologi membutuhkan kontekstualisasi hukum Islam. Banyak hal baru terjadi pada masa kini yang belum terjadi pada masa sebelumnya. Al-Qur''an dan Hadis sebagai - 80 - sumber hukum yang sempurna dipastikan sesuai dengan konteks kehidupan manusia kapanpun dan dimanapun. Al-Qur''an dan Hadis hadir untuk menjamin terciptanya kehidupan yang sejahtera, adil, dan damai. Islam hadir sebagai ramatan lil `alamin. Salah satu instrumen yang diperlukan agar pemahaman terhadap Al-Qur''an dan Hadis tidak menyimpang melalui Ilmu Ushul Fikih. Ushul Fikih memastikan bahwa kontekstualisasi tidak keluar dari norma yang benar dan menjadi tolok ukur validitas sebuah ijtihad, serta membentuk seseorang berpikir kritis, inklusif, dan menghargai perbedaan. Murid yang mempelajari Ushul Fikih mengetahui cara sebuah hukum digali dari sumbernya, penyebab perbedaan hasil ijtihad, serta cara menyikapinya. Dalam konteks keindonesiaan, Ushul Fikih menjadi instrumen dalam merawat kebinekaan dan NKRI sebagai wujud nyata ijtihad ulama nusantara yang cinta tanah air. Pembelajaran Ushul Fikih berupa kajian dogma agama Islam diupayakan sekontekstual mungkin disesuaikan dengan fakta, fenomena sosial keagamaan, dan perkembangan ilmu pengetahuan dan teknologi (IPTEK), sehingga pemahaman agama tidak tekstualis, tetapi fleksibel dan tetap dalam koridor metodologi yang valid. Dengan demikian, Ushul Fikih memiliki makna bagi kehidupan murid karena mewarnai cara berpikir, bersikap, dan bertindak dalam kehidupan bermasyarakat, berbangsa, dan bernegara. B. Tujuan Tujuan pembelajaran Ushul Fikih di Madrasah Aliyah Program Keagamaan sebagai berikut."},{"nama_elemen":"Sumber hukum","capaian_pembelajaran":"Islam yang digunakan oleh para ulama untuk memecahkan permasalahan yang dihadapi. Pengetahuan tentang sumber hukum ini akan merangsang murid untuk berpikir terbuka dan inklusif, sehingga semakin mencintai ilmu yang dipelajari."},{"nama_elemen":"Instrumen yang","capaian_pembelajaran":"diperlukan oleh seorang mujtahid dalam menganalisis sebuah permasalahan dalam hukum Islam. Pemahaman terhadap instrumen ini akan mendorong murid untuk berpikir kritis terhadap sebuah hukum yang difatwakan oleh ulama dalam menyikapi sebuah permasalahan sosial keagamaan."},{"nama_elemen":"Kaidah dalam","capaian_pembelajaran":"Fikih dan Ushul Fikih yang bersifat praktis dapat digunakan untuk menganalisis sebuah persoalan yang muncul berdasarkan ajaran Islam. Pemahaman terhadap kaidah ini sangat - 81 - berguna dalam membekali murid untuk menghadapi fenomena kehidupan yang penuh dinamika. Persoalan yang akan dihadapi murid di masa depan sangat dinamis sehingga membutuhkan analisis yang cepat dan tepat serta tidak menyimpang dari ajaran Islam."},{"nama_elemen":"Syarat-syarat dan tingkatan","capaian_pembelajaran":"mujtahid dalam Islam. Hal ini diperlukan untuk membentuk sikap kritis dan selektif dalam mengikuti pendapat ulama. C. Karakteristik Keberadaan wahyu Allah Swt. berupa Al-Qur''an dan Hadis Rasulullah saw. adalah bukti nyata cinta Allah dan Rasul-Nya kepada umat manusia agar mereka bahagia di dunia dan akhirat. Namun demikian sering kali cara yang salah dalam memahami wahyu menimbulkan paham yang melegitimasi kebencian dan perbuatan keji sebagai dogma Tuhan. Ushul Fikih memegang peran krusial untuk membentengi umat Islam dari kesalahan memahami hukum Allah Swt. Pembelajaran Ushul Fikih pada Madrasah Aliyah Program Keagamaaan mempelajari dasar, prinsip, dan kaidah hukum islam dalam teks berbahasa Arab untuk memahami cara menggali hukum dari sumber utama (Al-Qur''an, Hadis, ijmak, dan qiyas). Ushul Fikih merupakan seperangkat aturan atau kaidah yang dapat digunakan untuk menganalisis dalil-dalil syara'' sehingga diketahui hukum yang terkandung di dalamnya. Dengan ushul fikih, seseorang memiliki instrumen untuk menganalisis dalil naqli dengan benar untuk diaplikasikan pada permasalahan sosial keagamaan yang timbul di masa sekarang yang tidak ditemukan padanannya di masa sebelumnya. Pemahaman yang baik terhadap Ilmu Ushul Fikih akan mendorong seseorang untuk berpikir sistematis, kritis, kontekstual, dan berorientasi pada cinta diri dan sesama manusia, serta cinta lingkungan. Hal ini menjadi bekal penting bagi murid untuk menghadapi dinamika kehidupan yang selalu berkembang pesat. Generasi muslim masa depan perlu dibekali instrumen yang memungkinkan untuk berkembang mengikuti dinamika masyarakat tanpa melepaskan identitas utamanya sebagai umat Islam. Hasil ijtihad dari ulama nusantara, seperti keberadaan NKRI akan dipahami dengan benar. Pemahaman yang komprehensif terhadap hukum Islam sangat - 82 - diperlukan untuk dapat mempertahankan Islam yang rahmatan lil`alamin dalam konteks keindonesiaan, sebagai wujud cinta tanah air. Berikut elemen dan deskripsi Ilmu Ushul Fikih. Elemen Deskripsi Pemahaman Konsep dan perkembangan Fikih dan Ushul Fikih Konsep Menjelaskan konsep Fikih dan Ushul Fikih, tujuan dan ruang lingkupnya; merefleksi sejarah pertumbuhan dan perkembangan fikih dan ushul fikih. Sumber Hukum Islam Memahami fungsi, kedudukan dan penerapan sumber hukum yang disepakati (Al-Quran, Hadis, ijmak, qiyas), memahami fungsi, kedudukan dan penerapan sumber hukum yang diperselisihkan (istihsan, mashlahah mursalah, `urf, istishab, syar''u man qablana, dalalatul iqtiran, saddudz dzari''ah dan mazdhab shahabiy) Hukum Syar''i Merefleksikan konsep al-hakim; mengaplikasikan konsep al-hukmu, al-mahkum fih, dan al-mahkum `alaih. Kaidah Ushul Fikih Memahami penerapan kaidah amr dan nahi, `am dan khas, takhsis dan mukhassis, mujmal dan mubayyan, muradif dan musytarak, mutlaq dan muqayyad, zahir dan takwil, serta manthuq dan mafhum Ijtihad Memahami konsep ijtihad dan mujtahid, ta''arudhul adillah, nasikh dan mansukh, tarjih; merefleksikan taqlid dan talfiq. Kaidah Fikih Me"},{"nama_elemen":"Pemahaman Konsep Sejarah Fikih dan Ushul Fikih","capaian_pembelajaran":"Merefleksikan konsep Fikih dan Ushul Fikih, tujuan dan ruang lingkupnya,sejarah pertumbuhan dan perkembangan Fikih dan Ushul Fikih, serta mazhab dalam Fikih dan Ushul Fikih. Sumber Hukum Islam Menganalisis fungsi, kedudukan dan penerapan sumber hukum yang disepakati (Al-Qur''an, Hadis, ijmak, qiyas); menganalisis fungsi, kedudukan, dan penerapan sumberhukum yang diperselisihkan (istihsan, maslahah mursalah, `urf, istishab, syar''u man qablana, dalaalatul iqtiran, saddudz dzari''ah dan madzhab shahabiy). Hukum Syar''i Merefleksikan konsep al-hakim, al-hukmu, al-mahkum fih, dan almahkum `alaih. Kaiadah Ushul Fikih Menganalisis penerapan kaidah amr dan nahi, `aam dan khas, takhsis dan mukhassis, mujmal dan mubayyan, muradif dan musytarak, mutlaq dan muqayyad, zahir dan takwil, serta manthuq dan mafhum. Ijtihad Menganalisis konsep ijtihad dan mujtahid, ta''arudhul adillah, nasikh dan mansukh, tarjih, serta taqlid dan talfiq. - 84 - Kaidah Fikih Menganalisis penerapan kaidah al-umuuru bi maqashidiha, kaidah al-yaqinu laa yuzaalu bisy-syak, kaidah al-masyaqqatu tajlibu-taysir, kaidah adh-dhararu yuzal, dan kaidah al''aadatu muhakkamah."},{"nama_elemen":"Keterampilan Proses �","capaian_pembelajaran":"Mengamati Melakukan pengamatan terhadap fenomena sosial dan keagamaan di masyarakat dan hukum yang dikeluarkan oleh ulama terhadap hal tersebut. � Menanya Mengidentifikasi pertanyaan yang dapat diteliti secara ushul fikih yang setidaknya mendeskripsikan fenomena yang menjadi objek hukum, ulama yang mengeluarkan fatwa hukum serta dasar pijakan hukumnya. � Mengumpulkan data Murid mencari informasi berdasarkan pertanyaan yang telah diidentifikasi dari sumber primer atau sekunder melalui kajian pustaka, wawancara, observasi dan lain sebagainya. � Menganalisis data Dengan bimbingan guru, murid menganalisis data dari sisi hukum syar''i, sumber hukum, kaidah ushul, kaidah fikih, serta ijtihad dan mujtahid. � Menarik Kesimpulan Murid menarasikan temuan hasil investigasi terhadap hukum dari sebuah sebuah fenomena yang terjadi di masyarakat. � Mengomunikasikan Murid menyajikan informasi secara lisan, tulisan dan/atau media lain dalam bentuk digital maupun nondigital dalam bahasa Arab."}]', NULL, 187, false, NOW(), NOW())
