-- SEJARAH KEBUDAYAAN ISLAM | MI Fase C [3 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MI', 'madrasah', NULL, 'SEJARAH KEBUDAYAAN ISLAM', 'C', 'IV-VI', NULL, '[{"nama_elemen":"Fase C (Umumnya","capaian_pembelajaran":"untuk Kelas V dan VI Madrasah Ibtidaiyah) Pada akhir fase C, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Pemahaman Konsep","capaian_pembelajaran":"Merefleksikan dakwah Rasulullah saw. kepada kelompok nonmuslim di Madinah; menceritakan dan merefleksikan peristiwa menjelang akhir hayat Rasulullah saw. dalam kehidupan seharihari; merefleksikan kisah keteladanan Abu Bakar Ash-Shiddiq, Umar bin Khattab, Usman bin Affan, dan Ali bin Abi Thalib dalam kehidupan sehari-hari; menganalisis biografi Wali Sanga dalam mengembangkan Islam di Indonesia."},{"nama_elemen":"Keterampilan Proses Mengamati","capaian_pembelajaran":"Mengidentifikasi sejarah perkembangan Islam yang relevan hingga saat ini. Mempertanyakan dan memprediksi Merumuskan pertanyaan kritis yang dapat diteliti secara ilmiah dan membuat hipotesis sederhana dari pertanyaan tersebut. Merencanakan dan melakukan penyelidikan Menyusun rencana peyelidikan seperti studi literatur atau wawancara untuk mengumpulkan data guna menjawab pertanyaan yang telah dirumuskan; mengumpulkan data dari sumber primer/sekunder (AlQur''an, Hadis, buku sejarah). Memproses, menganalisis data dan informasi Mengolah data dalam bentuk peta konsep sejarah perkembangan Islam. Mengevaluasi dan Refleksi Mengidentifikasi kemungkinan penjelasan alternatif dalam rangka mengevaluasi kesimpulan; merefleksikan - 90 - ibrah atau pembelajaran yang diperoleh dari peristiwa yang diteliti, dihubungkan dengan konteks kehidupan kontemporer. Mengomunikasikan hasil Mengomunikasikan hasil penelitian secara sistematis dan utuh dalam bentuk laporan tertulis, presentasi, poster, infografik, ataupun sejenisnya."}]', NULL, 208, false, NOW(), NOW())
ON CONFLICT (sumber_regulasi, jalur, jenjang, tipe_pendidikan, mapel_kode, fase)
DO UPDATE SET elemen = EXCLUDED.elemen, mapel_nama = EXCLUDED.mapel_nama, updated_at = NOW();
-- SEJARAH KEBUDAYAAN ISLAM | MTs Fase D [3 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MTs', 'madrasah', NULL, 'SEJARAH KEBUDAYAAN ISLAM', 'D', 'VII-IX', NULL, '[{"nama_elemen":"Fase D (Umumnya","capaian_pembelajaran":"untuk Kelas VII, VIII, dan IX Madrasah Tsanawiyah) Pada akhir fase D, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Pemahaman Konsep","capaian_pembelajaran":"Merefleksikan sejarah dakwah Rasulullah saw. dalam menumbuhkembangkan prinsip rahmatan lil ''alamin pada periode Makkah; merefleksikan sejarah dakwah Rasulullah saw. dalam membangun peradaban masyarakat Madinah; mengapresiasi prestasi Khulafaurasyidin dalam membangun peradaban Islam; menganalisis perkembangan peradaban Islam pada masa Daulah Umayyah; menganalisis perkembangan peradaban Islam pada masa Daulah Abbasiyah; meneladan ulama/ilmuwan muslim Daulah Umayyah dalam memajukan peradaban Islam; meneladan ulama/ilmuwan muslim Daulah Abbasiyah dalam memajukan peradaban Islam; merefleksikan keteladanan kepemimpinan Umar bin Abdul Aziz; menganalisis peradaban Islam pada masa Daulah Ayyubiyah; meneladan ilmuwan Daulah Ayyubiyah; menganalisis sejarah perkembangan Islam di Indonesia; meneladan Wali Sanga dalam dakwah Islam yang harmonis; menganalisis peran lembaga pesantren dalam dakwah Islam di Indonesia; menumbuhkan sikap tangggung jawab dan berperan aktif dalam mengapresiasi nilai kearifan lokal; merefleksikan keteladanan dari tokoh pendiri organisasi kemasyarakatan Islam Indonesia."},{"nama_elemen":"Keterampilan Proses Mengamati Murid mencermati","capaian_pembelajaran":"fenomena kehidupan sehari-hari terkait sejarah kebudayaan Islam. - 91 - Menanya dan memprediksi Murid menyusun pertanyaan tentang hal yang ingin diketahui dengan rumus 5W 1H (what: apa, who: siapa, when: kapan, where: dimana, why: mengapa, dan how: bagaimana) dan memprediksi jawaban atas pertanyaan. Mengumpulkan informasi Murid mencari informasi dari sumber primer dan sekunder melalui web/sumber online dengan studi pustaka, studi dokumen atau arsip, wawancara, observasi. Menganalisis informasi Murid menyeleksi sumber, memverifikasi, triangulasi terhadap akurasi data dan fakta sejarah, menginterpretasi data dan fakta sejarah. Menyimpulkan Murid menarasikan dari hasil pengumpulan informasi terhadap permasalahan terkait materi pelajaran. Mengomunikasikan Murid menyajikan informasi Sejarah Kebudayaan Islam secara lisan, tulisan dalam bentuk digital dan/atau nondigital. Merefleksikan dan merencanakan projek Murid mengevaluasi pengalaman belajar, mengambil ibrah dari peristiwa sejarah, dan merencanakan projek lanjutan secara kolaboratif."}]', NULL, 208, false, NOW(), NOW())
ON CONFLICT (sumber_regulasi, jalur, jenjang, tipe_pendidikan, mapel_kode, fase)
DO UPDATE SET elemen = EXCLUDED.elemen, mapel_nama = EXCLUDED.mapel_nama, updated_at = NOW();
-- SEJARAH KEBUDAYAAN ISLAM | MA Fase E [3 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MA', 'madrasah', NULL, 'SEJARAH KEBUDAYAAN ISLAM', 'E', 'X-XI', NULL, '[{"nama_elemen":"Fase E (Umumnya","capaian_pembelajaran":"untuk Kelas X Madrasah Aliyah) Pada akhir fase E, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Pemahaman Konsep","capaian_pembelajaran":"Menganalisis kebudayaan masyarakat Arab sebelum Islam; membandingkan substansi dan strategi dakwah Rasulullah saw. periode Makkah dan Madinah; merefleksikan nilai hijrah Rasulullah saw. dan para sahabat; menganalisis substansi Piagam Madinah (Misaq al-Madinah) dan faktor-faktor keberhasilan Fathu Makkah; mengevaluasi proses pemilihan - 92 - Khulafaurasyidin; menganalisis substansi dan strategi dakwah Khulafaurasyidin; menerapkan nilai-nilai kepemimpinan Khulafaurasyidin; menganalisis proses berdirinya Daulah Umayyah dan Abbasiyah; menganalisis perkembangan peradaban dan ilmu pengetahuan pada masa Daulah Umayyah dan Abbasiyah; meneladan semangat keilmuan para tokoh muslim masa Daulah Umayyah dan Abbasiyah; mengevaluasi faktorfaktor kemajuan dan kemunduran Daulah Umayyah dan Abbasiyah."},{"nama_elemen":"Keterampilan Proses Mengamati Murid","capaian_pembelajaran":"mengidentifikasi sejarah perkembangan Islam yang relevan hingga saat ini. Menanya dan memprediksi Murid merumuskan pertanyaan kritis yang dapat diteliti secara ilmiah dan membuat hipotesis sederhana dari pertanyaan tersebut. Mengumpulkan informasi Murid mencari informasi dari sumber primer dan sekunder melalui studi pustaka, studi dokumen atau arsip, wawancara, observasi."}]', NULL, 208, false, NOW(), NOW())
