-- SEJARAH KEBUDAYAAN ISLAM | MA Fase F [3 elemen]
INSERT INTO capaian_pembelajaran (versi, versi_tanggal, sumber_regulasi, lampiran, jalur, jenjang, tipe_pendidikan, mapel_kode, mapel_nama, fase, kelas_umum, usia_mental, elemen, status_madrasah, halaman_perkiraan, deprecated, created_at, updated_at)
VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MA', 'madrasah', NULL, 'SEJARAH KEBUDAYAAN ISLAM', 'F', 'XII', NULL, '[{"nama_elemen":"Fase F (Umumnya","capaian_pembelajaran":"untuk Kelas XI dan XII Madrasah Aliyah) Pada akhir fase F, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Pemahaman Konsep","capaian_pembelajaran":"Menganalisis perkembangan peradaban dan ilmu pengetahuan pada masa Daulah Usmani, Mughal, dan Safawi; membandingkan peranan Daulah Usmani, Mughal, dan Safawi terhadap peradaban Islam dan dunia; menganalisis sistem pemerintahan, sosial politik, serta perkembangan budaya pada masa Daulah Usmani, Mughal, dan Safawi; menganalisis proses awal masuknya Islam di Nusantara dan ciri khas penyebaran Islam; mengevaluasi peran kerajaan-kerajaan Islam dalam perkembangan Islam di Nusantara; meneladan semangat Wali Sanga dalam mengembangkan stragegi dakwah dan membangun peradaban; menganalisis peran penting umat Islam Indonesia dalam perjuangan kemerdekaan dan pembangunan bangsa; - 93 - mengevaluasi organisasi pergerakan Islam yang berperan dalam perjuangan kemerdekaan; meneladan kontribusi umat Islam dalam perjuangan kemerdekaan dan kemajuan Indonesia."},{"nama_elemen":"Keterampilan Proses Mengamati Murid","capaian_pembelajaran":"mengidentifikasi sejarah perkembangan Islam yang relevan hingga saat ini. Menanya dan memprediksi Murid mengembangkan pertanyaan yang bersifat kritis dan dapat diuji secara ilmiah, lalu menyusun hipotesis dasar berdasarkan pertanyaan tersebut. Mengumpulkan informasi Murid merancang rencana penyelidikan, seperti studi kepustakaan atau wawancara, guna memperoleh data yang relevan untuk menjawab pertanyaan yang telah ditetapkan; serta menghimpun informasi dari sumber primer maupun sekunder, seperti Al-Qur`an, Hadis, kitab tarikh dan literatur sejarah. Menganalisis informasi Murid menganalisis informasi melalui penyusunan diagram linimasa yang menggambarkan perkembangan peradaban Islam sejak masa masa Daulah Usmani, Mughal, dan Safawi sampai dengan perkembangan Islam di Indonesia, serta memaparkan hasil kajian berdasarkan pengamatan tersebut. Menyimpulkan Murid menyimpulkan hasil penelitian atau pengumpulan informasi, dikaitkan dengan materi pembelajaran. Mengomunikasikan Murid menyampaikan hasil penelitian secara terstruktur dan menyeluruh melalui berbagai media, seperti laporan tertulis, presentasi lisan, poster, flyer, infografik, atau bentuk media ilmiah lainnya. Merefleksikan dan merencanakan projek Murid mengevaluasi pengalaman belajar, melakukan refleksi terhadap nilai-nilai atau pelajaran yang dapat dipetik dari peristiwa yang dikaji, dengan - 94 - mengaitkannya pada realitas kehidupan masa kini, dan merencanakan projek lanjutan secara kolaboratif."}]', NULL, 208, false, NOW(), NOW())
ON CONFLICT (sumber_regulasi, jalur, jenjang, tipe_pendidikan, mapel_kode, fase)
DO UPDATE SET elemen = EXCLUDED.elemen, mapel_nama = EXCLUDED.mapel_nama, updated_at = NOW();
