VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MI', 'madrasah', NULL, 'BAHASA ARAB MI/MTs/MA/MAK', 'C', 'IV-VI', NULL, '[{"nama_elemen":"Fase C (Umumnya","capaian_pembelajaran":"untuk kelas V dan VI MI) Pada akhir fase C, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Komponen Bahasa","capaian_pembelajaran":"Mengidentifikasi informasi dan bacaan sederhana tentang anggota tubuh, kebun binatang, di ruang tamu dan di ruang belajar, di perpustakaan, di kantin, dengan pola kalimat di antaranya: - 99 - ; ; ; ;; serta mengidentifikasi informasi dan bacaan sederhana tentang jam, saya suka bahasa Arab, saya suka kegiatan liburan, piknik, dengan pola kalimat di antaranya: ; ; ; ; ;"},{"nama_elemen":"Keterampilan Bahasa","capaian_pembelajaran":"Menerapkan keterampilan berbahasa yang meliputi kegiatan menyimak, berbicara, membaca, memirsa, menulis, dan mempresentasikan."}]', NULL, 225, false, NOW(), NOW())
