VALUES ('9941/2025', '2025-11-28', 'Kep Dirjen Pendis 9941/2025', 'I', 'kneelmenag', 'MTs', 'madrasah', NULL, 'BAHASA ARAB MI/MTs/MA/MAK', 'D', 'VII-IX', NULL, '[{"nama_elemen":"Fase D (Umumnya","capaian_pembelajaran":"untuk kelas VII, VIII, dan IX MTs) Pada akhir fase D, murid memiliki kemampuan sebagai berikut."},{"nama_elemen":"Komponen Bahasa","capaian_pembelajaran":"Menganalisis kosa kata, pola kalimat, dan wacana tentang: -/ -den/gand-d peenon-lgagaanknapdlpioemolna/laag--katknaalilp-mi mo al/aa ttka-l/im-at// - /--/ d e nganp ol-akalim at - - dengan pola kalimat - - - 100 - dedd neegnnaggnaa nnp opploaollaak akklaiamlliimma taatt - - dengan p ol addeked nane glgniamagnnaanptpoopllaoalkakaaklliaimm-lima attat - d e nd ge andngeanpngoalpanoklpaaolkliamalkiamatlaimt at � -"},{"nama_elemen":"Keterampilan Bahasa","capaian_pembelajaran":"Menerapkan komponen bahasa melalui keterampilan bahasa, yaitu menyimak, berbicara, membaca, memirsa, menulis, dan mempresentasikan. Proses ini dilakukan dengan cara mengidentifikasi informasi secara tersurat dan tersirat dari wacana lisan, mengaplikasi wacana lisan, menganalisis teks visual atau multimodal, dan memproduksi gagasan secara tertulis dan/atau lisan tentang tema dan pola kalimat tersebut."}]', NULL, 225, false, NOW(), NOW())
